---------- General classes --------------- */
html {
	-webkit-text-size-adjust: 100%;
}
body
{
	font-family: Arial, sans-serif;
	font-size: 13px;
	color: #343434;
	padding: 0px;
	margin: 0px;
	background:#fff;
		
}
input, button
{
}

p
{
    padding: 0 0 15px;
    margin: 0;
}
a
{
    color: #007bc3;
    text-decoration: none;
    padding: 1px;
}
a:hover
{
    text-decoration: none;
    color: #0a2f73;
}
 
a:focus, li:focus, div:focus, span:focus, button:focus, select:focus, input:focus {
	outline: none !important;
}
.page {

	min-height:1000px;	
}
.fe-chart-body .page{
	position:relative;
	padding-top:0;
}
div.backButton {
    padding-bottom: 0;
    position: absolute;
    top: -15px;
    right: 0;
}
div.backButton .fe-back-button {
    margin: 0 !important;
    background-color: transparent !important;
    border: 0 !important;
    padding: 0 !important;
    font-size: 0 !important;
    font-weight: bold !important;
    color: #fff !important;
	height:20px;
	padding:0px 30px 0 28px !important;
	position:relative;
	
    background-image:url(fe_img/back-arw3.png) !important;
	background-repeat:no-repeat !important;
	background-position:0 50% !important;
}
div.backButton .fe-back-button:before{
	position:absolute;
	z-index:1;
	content:"Go Back";
	width:50px;
	height:20px;
	right:0;
	top:4px;
	display:block;
	font-size:11px;
	color:#fff;
	text-align:right;
}
ul, li {
	list-style-type: none !important;
}

.ui-page-content-panel{
	/* background:url(fe_img/sl_pattern.png) no-repeat right -6px; */
	position: relative;
}

.ui-widget
{
    font-family:  Arial, sans-serif;
}
.ui-state-default, .ui-widget-content .ui-state-default, .ui-widget-header .ui-state-default, .ui-widget-header
{
    background-image: none;
    background: none;
    border: none;
}
